import java.util.*; class Solution { private static class TrieNode { TrieNode[] children = new TrieNode[26]; String word = null; } private void insert(TrieNode root, String word) { TrieNode curr = root; for (char c : word.toCharArray()) { int idx = c - 'a'; if (curr.children[idx] == null) curr.children[idx] = new TrieNode(); curr = curr.children[idx]; } curr.word = word; } public List<String> findWords(char[][] board, String[] words) { TrieNode root = new TrieNode(); for (String w : words) insert(root, w); List<String> result = new ArrayList<>(); int m = board.length, n = board[0].length; for (int i = 0; i < m; i++) { for (int j = 0; j < n; j++) { dfs(board, i, j, root, result); } } return result; } private void dfs(char[][] board, int r, int c, TrieNode node, List<String> res) { char ch = board[r][c]; if (ch == '#' || node.children[ch - 'a'] == null) return; node = node.children[ch - 'a']; if (node.word != null) { res.add(node.word); node.word = null; } board[r][c] = '#'; int[] dr = {0, 0, 1, -1}; int[] dc = {1, -1, 0, 0}; for (int i = 0; i < 4; i++) { int nr = r + dr[i], nc = c + dc[i]; if (nr >= 0 && nr < board.length && nc >= 0 && nc < board[0].length) { dfs(board, nr, nc, node, res); } } board[r][c] = ch; } }